 "content": "def transform(grid):
    """Sort hollow frame objects upward and the other objects downward."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            todo = [(r, c)]
            seen.add((r, c))
            cells = []
            while todo:
                y, x = todo.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        todo.append((ny, nx))
            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)
            points = set(cells)
            hollow = any((y, x) not in points
                         for y in range(top + 1, bottom)
                         for x in range(left + 1, right))
            objects.append({"color": color, "cells": cells, "top": top,
                            "bottom": bottom, "hollow": hollow})

    def positions(obj, top):
        dy = top - obj["top"]
        return {(y + dy, x) for y, x in obj["cells"]}

    def fits(obj, top, occupied):
        pts = positions(obj, top)
        return all(0 <= y < h and 0 <= x < w and (y, x) not in occupied for y, x in pts)

    placed = []
    occupied_frames = set()
    # Hollow rectangular outlines rise, keeping their x coordinates fixed.
    for obj in sorted((o for o in objects if o["hollow"]), key=lambda o: (o["top"], o["left"])):
        for new_top in range(obj["top"] + 1):
            if fits(obj, new_top, occupied_frames):
                chosen = new_top
                break
        occupied_frames |= positions(obj, chosen)
        placed.append((obj, chosen))

    occupied_other = set()
    # Solid symbols fall, processing lower ones first so the shapes stack.
    for obj in sorted((o for o in objects if not o["hollow"]),
                      key=lambda o: (-o["bottom"], o["left"])):
        max_top = h - 1 - (obj["bottom"] - obj["top"])
        chosen = obj["top"]
        for new_top in range(max_top, obj["top"] - 1, -1):
            if fits(obj, new_top, occupied_other):
                chosen = new_top
                break
        occupied_other |= positions(obj, chosen)
        placed.append((obj, chosen))

    out = [[0] * w for _ in range(h)]
    for obj, top in placed:
        for y, x in positions(obj, top):
            out[y][x] = obj["color"]
    return out
